def recover_cards(n, d, l):
    if n == 2:
        if d < 0 or d > l:
            return "-1"
        return f"{d + 1} {l}"

    if n == 3:
        if d < -l or d > l:
            return "-1"
        return f"{l} {1} {l - d}"

    if n == 4:
        if d < -2 * l or d > 2 * l:
            return "-1"
        return f"{l} {1} {l} {1 - d}"

    if n == 5:
        if d < -3 * l or d > 3 * l:
            return "-1"
        return f"{l} {1} {l} {1} {l - d}"

    # For n > 5, we can use a general approach
    if d < -(n - 1) * l or d > (n - 1) * l:
        return "-1"

    cards = [l] * (n - 1)
    cards.append(l - d)
    return " ".join(map(str, cards))

